/** Concurrent HTTP family writes/idempotency/owner gates over owned disk state. */
import assert from 'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{join}from'node:path';import{performance,monitorEventLoopDelay}from'node:perf_hooks';
import{initDatabase,getDb,closeDatabase}from'../../src/db/connection.js';import{createWebSession,revokeUserWebSessions}from'../../src/db/web-sessions.js';
import{getUser}from'../../src/db/users.js';import{provisionFamilyAccount,updateManagedAccount}from'../../src/db/account-administration.js';
import{resolveRequestPrincipal}from'../../src/channels/web/auth/principal.js';import{WebAuthGateway}from'../../src/channels/web/auth/auth-gateway.js';import{TotpFailureTracker}from'../../src/channels/web/auth/totp-failure-tracker.js';import{WebauthnChallengeTracker}from'../../src/channels/web/auth/webauthn-challenges.js';import{RequestRouterService}from'../../src/channels/web/request-router-service.js';import{assertPathWithinTestFilesystemIsolation}from'../../scripts/test-filesystem-isolation.js';
import type{AuthenticatedPrincipal}from'../../src/core/access-types.js';
const workspace=process.env.PICLAW_WORKSPACE!;assertPathWithinTestFilesystemIsolation(workspace,process.env,{allowRoot:false});assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');
mkdirSync(join(workspace,'.piclaw'),{recursive:true});writeFileSync(join(workspace,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode:'family-shared'}}}));const originalFetch=globalThis.fetch;let server:ReturnType<typeof Bun.serve>|undefined;let loop:ReturnType<typeof monitorEventLoopDelay>|undefined;let blocker:ReturnType<typeof Bun.spawn>|undefined;
try {
initDatabase();const db=getDb();
function principal(id:string,token:string){const login=createWebSession(token,id,3600,'passkey');return resolveRequestPrincipal(new Request('https://synthetic.invalid',{headers:{cookie:'piclaw_session=synthetic-principal'}}),{mode:'family-shared',authEnabled:true},{getSession:()=>login,getUser:()=>getUser(db,id),getLocalDisplayName:()=> 'Synthetic'})!}
const admin=principal('default','synthetic-admin'),users:AuthenticatedPrincipal[]=[],tokens=['synthetic-alice','synthetic-bob'];
for(const name of['alice','bob']){const user=provisionFamilyAccount(db,admin,{username:name,displayName:name});db.query("INSERT INTO webauthn_credentials(user_id,rp_id,credential_id,public_key)VALUES(?,'localhost',?,'synthetic')").run(user.id,name);updateManagedAccount(db,admin,user.id,{enabled:true},{totp:false,passkey:true,rpId:'localhost'});users.push(principal(user.id,tokens[users.length]));}
let wakes=0,broadcasts=0;const json=(v:unknown,s=200)=>Response.json(v,{status:s});const gateway=new WebAuthGateway({accessMode:'family-shared',passkeyMode:'',totpSecret:'',internalSecret:'',hasTls:false,sessionTtlSeconds:3600},{json,challenges:new WebauthnChallengeTracker(),failureTracker:new TotpFailureTracker()});
const channel={authGateway:gateway,json,endpointContexts:{auth:()=>({})},broadcastEvent:()=>{broadcasts++},resumeChat:()=>{wakes++},agentPool:{isStreaming:()=>false},clampInt:()=>50,parseOptionalInt:()=>null}as any;
const router=new RequestRouterService(channel,'family-shared');server=Bun.serve({hostname:'127.0.0.1',port:0,fetch:req=>router.handle(req)});const ownedServer=server;let external=0;globalThis.fetch=Object.assign(async(input:any,init:any)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url);if(url.origin!==ownedServer.url.origin){external++;throw Error('external denied')}return originalFetch(input,init)},{preconnect(){external++;throw Error('preconnect denied')}})as typeof fetch;
let memoryReadRetries=0;
function sampleMemory(){for(let attempt=0;;attempt++){try{return process.memoryUsage()}catch(error){if((error as {errno?:number}).errno!==4||attempt>=2)throw error;memoryReadRetries++}}}
const start=performance.now(),cpu=process.cpuUsage();loop=monitorEventLoopDelay({resolution:1});loop.enable();const phases=[];
async function send(owner:number,index:number,options:{foreign?:boolean;hostileOrigin?:boolean;different?:boolean}={}){const target=users[options.foreign?1-owner:owner].homeChatJid!;const response=await fetch(new URL('/agent/default/message?chat_jid='+encodeURIComponent(target),ownedServer.url),{method:'POST',headers:{cookie:'piclaw_session='+tokens[owner],origin:options.hostileOrigin?'https://foreign.invalid':ownedServer.url.origin,'content-type':'application/json','x-piclaw-account-id':users[owner].userId,'x-piclaw-login-id':users[owner].authentication.sessionId!},body:JSON.stringify({content:options.different?'Conflicting synthetic body':'Synthetic family request '+index,request_id:'family-request-'+index,mode:'queue'})});const body=await response.json();return{status:response.status,body}}
async function phase(name:string,fn:()=>Promise<void>){const at=performance.now();await fn();phases.push({name,wallMs:performance.now()-at})}
 await phase('concurrent-owner-admission',async()=>{for(let batch=0;batch<4;batch++){const result=await Promise.all(Array.from({length:4},(_,n)=>send(n%2,batch*2+Math.floor(n/2))));assert(result.every(r=>r.status===201));await Bun.sleep(5)}});
 const count=()=>Number((db.query('SELECT count(*)AS n FROM messages').get()as{n:number}).n);assert.equal(count(),16);
 await phase('parallel-exact-replay',async()=>{const result=await Promise.all([send(0,0),send(1,0),send(0,1),send(1,1)]);assert(result.every(r=>r.status===200))});assert.equal(count(),16);
 await phase('foreign-csrf-conflicting-denials',async()=>{const result=await Promise.all([send(0,10,{foreign:true}),send(1,10,{hostileOrigin:true}),send(0,0,{different:true}),send(1,0,{different:true})]);assert(result.every(r=>r.status===403));for(const r of result)assert.deepEqual(r.body,{error:'Session access denied.'})});assert.equal(count(),16);
 const authorities=db.query('SELECT a.owner_user_id,a.actor_user_id,a.login_session_id,m.chat_jid FROM message_execution_authorities a JOIN messages m ON m.rowid=a.message_rowid').all()as any[];assert.equal(authorities.length,16);const namespaced=db.query('SELECT owner_user_id,request_id,chat_jid FROM message_execution_authorities ORDER BY owner_user_id,request_id').all()as Array<{owner_user_id:string;request_id:string;chat_jid:string}>;for(const owner of users){const own=namespaced.filter(r=>r.owner_user_id===owner.userId);assert.equal(own.length,8);assert.deepEqual(own.map(r=>r.request_id).sort(),Array.from({length:8},(_,n)=>'family-request-'+n));assert(own.every(r=>r.chat_jid===owner.homeChatJid))}for(const a of authorities){const owner=users.find(u=>u.userId===a.owner_user_id);assert(owner);assert.equal(a.actor_user_id,owner.userId);assert.equal(a.login_session_id,owner.authentication.sessionId);assert.equal(a.chat_jid,owner.homeChatJid)}
 assert.equal((db.query("SELECT count(*)AS n FROM family_turn_queue WHERE state='ready'").get()as any).n,2);assert.equal((db.query("SELECT count(*)AS n FROM family_turn_queue WHERE state='held'").get()as any).n,14);assert.equal(wakes,4);assert.equal(broadcasts,16);
 const contention=process.argv[2]??'none';assert(['none','release','revoke'].includes(contention));let contentionObservation:unknown=null;
 if(contention!=='none'){
  blocker=Bun.spawn([process.execPath,'--no-env-file','-e','import{Database}from"bun:sqlite";const d=new Database(process.argv[1]);d.exec("BEGIN IMMEDIATE");console.log("LOCKED");await Bun.sleep(500);if(process.argv[2]==="revoke")d.query("DELETE FROM web_sessions WHERE user_id=?").run(process.argv[3]);d.exec("COMMIT");d.close()',join(process.env.PICLAW_STORE!,'messages.db'),contention,users[1].userId],{env:{PATH:process.env.PATH,HOME:process.env.HOME},stdout:'pipe',stderr:'pipe'});
  const lock=blocker.stdout.getReader();const first=await lock.read();assert(new TextDecoder().decode(first.value).includes('LOCKED'));lock.releaseLock();
  await Bun.sleep(5);loop.reset();
  const at=performance.now();let timerMs=0;
  const timer=new Promise<void>(resolve=>setTimeout(()=>{timerMs=performance.now()-at;resolve()},10));
  const pending=send(1,12);
  const read=(async()=>{const response=await fetch(new URL('/timeline?chat_jid='+encodeURIComponent(users[0].homeChatJid!),ownedServer.url),{headers:{cookie:'piclaw_session='+tokens[0]}});assert.equal(response.status,200);const body=await response.json();assert(body.posts.length>0);assert(body.posts.every((p:any)=>p.chat_jid===users[0].homeChatJid));return performance.now()-at})();
  const [observed,unrelatedReadMs]=await Promise.all([pending,read,timer]);await blocker.exited;assert.equal(blocker.exitCode,0);
  assert.equal(observed.status,contention==='revoke'?403:201);if(contention==='revoke'){assert.deepEqual(observed.body,{error:'Session access denied.'});assert.equal(count(),16)}else assert.equal(count(),17);
  contentionObservation={mode:contention,writerLockedBeforeRequest:true,heldMs:500,responseStatus:observed.status,elapsedMs:performance.now()-at,unrelatedReadMs,timerMs,eventLoopMaxMs:loop.max/1e6,eventLoopSamples:loop.count,rowsAfter:count(),noRevokedAdmission:contention==='revoke'?count()===16:null};
 }
 revokeUserWebSessions(users[0].userId);const revoked=await send(0,11);assert.equal(revoked.status,401);assert.deepEqual(revoked.body,{error:'Unauthorized'});assert.equal(count(),contention==='release'?17:16);assert.equal(external,0);assert.deepEqual(db.query('PRAGMA quick_check').get(),{quick_check:'ok'});await Bun.sleep(10);loop.disable();
 console.log(JSON.stringify({runtime:Bun.version,ownerAdmissions:16,exactReplays:4,denials:{foreign:1,csrf:1,conflictingPayload:2,revoked:1},concurrency:4,immutableAuthorityVerified:true,contention:contentionObservation,queue:{ready:2,held:14},wakeSinkCalls:wakes,broadcastSinkCalls:broadcasts,wallMs:performance.now()-start,cpu:process.cpuUsage(cpu),phases,eventLoop:{samples:loop.count,maxMs:loop.max/1e6,meanMs:loop.mean/1e6},memory:sampleMemory(),memoryReadRetries,settings:{journal:db.query('PRAGMA journal_mode').get(),synchronous:db.query('PRAGMA synchronous').get()},external,scope:'Direct DB/service account/session setup, then actual owned loopback RequestRouter family mutation/CSRF/browserpins/admission/idempotency/immutable owner SQL/queue writes. Sameprocessrequests atconcurrency4; SQLite serializes transactions. Wake/broadcast are sinks, no Agent/dequeue/delivery/provider; optional crossprocess IMMEDIATE writer holds500ms then commits release or targetlogin revocation. Initial queue/authority counts refer to pre-contention phase; no live accounts. Wall/CPU includes intentional sleeps; replaced global fetch counts only calls through that wrapper, not universal network isolation.'}));
}finally{if(blocker?.exitCode===null){blocker.kill('SIGKILL');await blocker.exited}loop?.disable();globalThis.fetch=originalFetch;try{server?.stop(true)}finally{closeDatabase()}}
